using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.Tilemaps;using UnityEditor;using UnityEditor.SceneManagement;public static class ShiftMinePath{public static object Main(){var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(s.isDirty||EditorApplication.isPlaying)throw new Exception("Clean edit required");File.Copy(s.path,"output/scene-review/Main.before-minepath-disk.unity",true);EditorSceneManager.SaveScene(s,"output/scene-review/Main.before-minepath-live.unity",true);int n=0;foreach(var m in GameObject.Find("Hometown").GetComponentsInChildren<Tilemap>(true).Where(m=>m.name=="-2 Old Path"||m.name=="-1 Path")){Undo.RegisterCompleteObjectUndo(m,"Move mine path one tile left");for(int y=10;y<=12;y++){var p=new Vector3Int(-36,y,0);var t=m.GetTile(p);if(t==null)throw new Exception("Missing path cell");m.SetTile(p+Vector3Int.left,t);m.SetTile(p,null);}n++;}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s,"output/scene-review/Main.after-minepath-live.unity",true);return new{layers=n,shiftCells=1};}}
